# Initialize an empty phonebook dictionary
phonebook = {}

def add_contact(name, number):
    """Add a contact to the phonebook."""
    if name in phonebook:
        print(f"{name}: {number} already exists in the phonebook.")
    else:
        phonebook[name] = number
        print(f"{name}: {number} has been added to the phonebook.")

def remove_contact(name):
    """Remove a contact from the phonebook."""
    if name in phonebook:
        del phonebook[name]
        print(f"{name} has been removed from the phonebook.")
    else:
        print(f"{name} is not in the phonebook.")

def search_contact(name):
    """Search for a contact in the phonebook."""
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"{name} is not in the phonebook.")

# Example usage
add_contact("John", "123-456-7890")
add_contact("Jane", "543-210-9876")
remove_contact("John")
search_contact("Jane")
```

This program defines three functions: `add_contact`, `remove_contact`, and `search_contact`. The `add_contact` function adds a contact to the phonebook, the `remove_contact` function removes a contact from the phonebook, and the `search_contact` function searches for a contact in the phonebook. The program also includes example usage to demonstrate the functionality.
